import os
import re

DEFAULTS = {
    "PAYHOOK_API_TOKEN": None,
    "PAYHOOK_WEBHOOK_SECRET": None,
    "PAYHOOK_ENDPOINT": "https://api.payments.example/v1",
    "PAYHOOK_TIMEOUT": "10",
    "PAYHOOK_REGION": "eu",
}

# Values of these settings are never printed in full.
SECRET_KEYS = {"PAYHOOK_API_TOKEN", "PAYHOOK_WEBHOOK_SECRET"}

_ASSIGNMENT = re.compile(r"^(?:export\s+)?([A-Za-z_][A-Za-z0-9_.-]*)\s*=(.*)$")
_DOUBLE_ESCAPES = {'"': '"', "\\": "\\", "n": "\n"}


def _parse_value(raw, where):
    raw = raw.strip()
    if raw[:1] in ("'", '"'):
        quote = raw[0]
        chars = []
        i = 1
        while i < len(raw):
            c = raw[i]
            if quote == '"' and c == "\\" and i + 1 < len(raw):
                nxt = raw[i + 1]
                chars.append(_DOUBLE_ESCAPES.get(nxt, c + nxt))
                i += 2
                continue
            if c == quote:
                rest = raw[i + 1:].strip()
                if rest and not rest.startswith("#"):
                    raise ValueError(f"{where}: unexpected text after closing quote")
                return "".join(chars)
            chars.append(c)
            i += 1
        raise ValueError(f"{where}: unterminated {quote} quote")
    if raw.startswith("#"):
        return ""
    # Unquoted values end at an inline comment: whitespace followed by '#'.
    return re.split(r"\s+#", raw, maxsplit=1)[0].strip()


def read_dotenv(path):
    values = {}
    if not os.path.exists(path):
        return values
    with open(path, encoding="utf-8") as handle:
        for lineno, line in enumerate(handle, 1):
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            where = f"{path}:{lineno}"
            match = _ASSIGNMENT.match(line)
            if not match:
                raise ValueError(f"{where}: expected KEY=value")
            key, raw = match.groups()
            values[key] = _parse_value(raw, where)
    return values


def load_config(environ=None, dotenv_path=".env"):
    environ = os.environ if environ is None else environ
    dotenv = read_dotenv(dotenv_path)
    config = {}
    for key, default in DEFAULTS.items():
        if key in environ:
            config[key] = (environ[key], "env")
        elif key in dotenv:
            config[key] = (dotenv[key], ".env")
        else:
            config[key] = (default, "default")
    return config


_SOURCE_LABELS = {"env": "environment", ".env": ".env", "default": "default"}


def doctor_report(config, dotenv_path, dotenv_found, python_version, cwd):
    lines = [
        "payhook doctor",
        f"python: {python_version}",
        f"working directory: {cwd}",
        f"dotenv file: {dotenv_path} ({'found' if dotenv_found else 'not found'})",
        "settings:",
    ]
    width = max(len(key) for key in config)
    for key, (value, source) in config.items():
        if value is None:
            shown = "(not set)"
        elif key in SECRET_KEYS:
            shown = f"(set, {len(value)} characters, redacted)"
        else:
            shown = repr(value)
        lines.append(f"  {key.ljust(width)} = {shown}  [source: {_SOURCE_LABELS[source]}]")
    return "\n".join(lines)

